SET county = NULL
WHERE target.county IS NOT NULL
  AND btrim(target.county) = '';--> statement-breakpoint

UPDATE "patients" AS target
SET sub_county = NULL
WHERE target.sub_county IS NOT NULL
  AND btrim(target.sub_county) = '';--> statement-breakpoint

