      WHERE lower(btrim(regexp_replace(record.county, '\s+', ' ', 'g'))) = v.county
        AND lower(btrim(regexp_replace(record.sub_county, '\s+', ' ', 'g'))) = v.sub_county
    )
), audited AS (
  INSERT INTO "audit_logs" (tenant_id, facility_id, action, resource, resource_id, details)
  SELECT doomed.tenant_id,
         doomed.registration_facility_id,
         'UPDATE',
         'Patient',
         doomed.id::text,
         'Location cleanup (0023): sub-county "'
           || doomed.sub_county
           || '" does not belong to county '
           || coalesce('"' || doomed.county || '"', '(none)')
           || '; sub-county cleared. The previous value is in this entry.'
  FROM doomed
  RETURNING 1
)
UPDATE "patients" AS target
SET sub_county = NULL
FROM doomed
WHERE target.id = doomed.id;--> statement-breakpoint

